command:
/**
 * SVA example: Shield Toggle
 * A shimmering magical shield around each selected token. It follows the token, survives a
 * reload, and bursts when you run the macro again.
 *
 * Usage: select tokens, run.
 * Requires: Sargas Visual Automation + JB2A. No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const COLOR = "blue"; // blue, green, purple, red, yellow
const SCALE = 1.5;
const BURST_ON_END = true; // play the "explode" outro instead of a plain fade

const tokens = canvas.tokens.controlled;
if (!tokens.length) return ui.notifications.warn("Select at least one token.");
const sceneId = canvas.scene.id;

for (const tok of tokens) {
  const name = `sva-shield:${tok.id}`;
  const seq = SVA.sequence();
  if (SVA.effects.list({ sceneId, name }).length) {
    await SVA.effects.end({ name, sceneId });
    if (BURST_ON_END) {
      seq.effect().file(`jb2a.shield.01.outro_explode.${COLOR}`).attachTo(tok.id).scaleToObject(SCALE);
      await seq.play();
    }
    continue;
  }
  // The "complete" file contains intro, loop and outro; persist() keeps it in the loop.
  seq
    .effect()
    .file(`jb2a.shield.01.complete.01.${COLOR}`)
    .attachTo(tok.id)
    .scaleToObject(SCALE)
    .fadeOut(BURST_ON_END ? 200 : 600)
    .persist(true)
    .name(name);
  await seq.play();
}
